/// Sets the element at index `i` of vector `a` to `val`.
/// Panics if `i` is out of bounds.
fn set_at(a: &mut Vec<i32>, i: usize, val: i32) {
    // This will panic if `i >= a.len()`, which matches the intended behavior
    // for out‐of‐bounds access.
    a[i] = val;
}

/// Overwrites every element of `a` with `N + 1`.
/// 
/// `a` must have length exactly `N` (where `N` > 0),
/// and `sum` must be a vector of length 1. Neither vector’s length is changed.
fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    // Convert N to usize, since Vec indices are usize.
    let n = N as usize;

    // Enforce the preconditions (will panic in debug/release builds if violated).
    assert_eq!(
        a.len(),
        n,
        "Primary array length ({}) must equal N ({})",
        a.len(),
        N
    );
    assert_eq!(
        sum.len(),
        1,
        "Auxiliary array length must be exactly 1, but is {}",
        sum.len()
    );

    // Compute the new value to set.
    let new_val = N + 1;

    // Overwrite each element in `a` using the helper `set_at`.
    for i in 0..n {
        set_at(a, i, new_val);
    }

    // We leave `sum` untouched (its length remains 1 as required).
}

